import {uiIcon} from '../ui-icons.mjs';
export function visibleMoonEntries(entries,family,tile){return entries.filter(e=>family==='moon'?!e.embedded:family==='ranch'&&e.embedded&&e.id===tile);}
const entries=new Map();let panel=null,selectedId=null,lastTile=null;
function ensurePanel(){if(panel)return;const style=document.createElement('style');style.textContent='.moon-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:12px;padding-top:12px;border-top:1px solid var(--app-border);font:12px var(--app-font,system-ui)}.moon-actions[hidden]{display:none!important}.moon-actions button{display:flex;align-items:center;justify-content:flex-start;gap:7px;min-height:44px;padding:7px 9px;border:1px solid var(--app-border);border-radius:8px;background:var(--app-paper);color:var(--app-ink);font:inherit}.moon-actions svg{width:19px;height:19px;flex:none}.moon-actions button:disabled{opacity:.5;cursor:default}.moon-actions-label{grid-column:1/-1;margin:4px 0 -2px;font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--app-muted,#7a7262)}.moon-actions button[data-state]::after{content:attr(data-state);margin-left:auto;padding:1px 6px;border-radius:9px;background:var(--app-border);font-size:10px;white-space:nowrap}.moon-actions button[aria-pressed=true]{outline:2px solid var(--app-accent,#b84931);outline-offset:-2px}.moon-actions select,.moon-actions output{grid-column:1/-1;max-width:100%;font:inherit}.moon-actions output{line-height:1.5;color:var(--app-ink)}.moon-actions[data-standalone=true]{position:fixed;right:12px;top:76px;width:260px;padding:14px;background:var(--app-paper);border:1px solid var(--app-border);border-radius:12px;z-index:20}';document.head.append(style);panel=document.createElement('div');panel.className='moon-actions';panel.setAttribute('aria-label','Moonbase flight controls');panel.innerHTML='<select aria-label="VIP destination Moonbase"></select><small class="moon-actions-label">Do</small><button type="button" data-action="vip">Call our VIP ship</button><button type="button" data-action="supply">Request supplies</button><small class="moon-actions-label">Watch</small><button type="button" data-action="follow">Follow VIPs</button><button type="button" data-action="interior">Show interior</button><output></output>';document.body.append(panel);new MutationObserver(render).observe(document.body,{subtree:true,attributes:true,attributeFilter:['data-selected-tile','data-family']});panel.querySelector('select').onchange=e=>{selectedId=e.target.value;render();};}
function render(){ensurePanel();const family=document.body.dataset.family,eligible=[...entries.values()].filter(e=>family==='moon'?!e.embedded:family==='ranch'&&e.embedded);const tile=document.querySelector('canvas[data-selected-tile]')?.dataset.selectedTile;const relevant=visibleMoonEntries([...entries.values()],family,tile);panel.hidden=!relevant.length;if(!relevant.length)return;const host=family==='moon'?document.body:document.querySelector('#inspection');if(host&&panel.parentElement!==host)host.append(panel);panel.dataset.standalone=String(family==='moon');if(tile!==lastTile&&eligible.some(e=>e.id===tile))selectedId=tile;lastTile=tile;const entry=relevant.find(e=>e.id===selectedId)||relevant[0];selectedId=entry.id;const select=panel.querySelector('select'),signature=eligible.map(e=>e.id+e.label).join('|');if(select.dataset.signature!==signature){select.replaceChildren(...eligible.map(e=>{const o=document.createElement('option');o.value=e.id;o.textContent=e.label;return o;}));select.dataset.signature=signature;}select.value=entry.id;select.hidden=family!=='moon'||eligible.length<2;const sim=entry.getSimulation(),v=sim.state.rocket.vip,a=sim.vipAvailability(),vipButton=panel.querySelector('[data-action=vip]'),supply=panel.querySelector('[data-action=supply]'),inside=panel.querySelector('[data-action=interior]');vipButton.disabled=!a.ready;const vipState=vipStage(v);vipButton.innerHTML=uiIcon('rocket')+'<span>'+(a.ready||vipState?'Call VIP ship':'Needs 80 m pad')+'</span>';if(vipState)vipButton.dataset.state=vipState;else delete vipButton.dataset.state;vipButton.removeAttribute('title');vipButton.onclick=()=>{if(sim.requestVip()){entry.refresh?.();document.dispatchEvent(new CustomEvent('moon-vip-state-changed',{detail:{resume:true,destination:entry.id}}));}render();};const availability=sim.dispatchAvailability();supply.disabled=!availability.ready;supply.innerHTML=uiIcon('supply')+'<span>Supplies</span>';if(sim.state.rocket.dispatch)supply.dataset.state='Inbound';else delete supply.dataset.state;supply.setAttribute('aria-label','Request supplies');supply.removeAttribute('title');supply.onclick=()=>{sim.requestDropship();document.dispatchEvent(new CustomEvent('moon-vip-state-changed'));render();};const follow=panel.querySelector('[data-action=follow]');follow.innerHTML=uiIcon('follow')+'<span>Follow VIPs</span>';follow.disabled=!v||['home','waiting-for-pad'].includes(v.phase);follow.onclick=()=>document.dispatchEvent(new CustomEvent('moon-vip-focus',{detail:{destination:entry.id}}));inside.hidden=!entry.interior?.interiorAvailable;inside.disabled=!entry.interior?.interiorDocked;inside.innerHTML=uiIcon('interior')+'<span>'+(entry.interior?.interiorOpen?'Close hull':'Interior')+'</span>';inside.setAttribute('aria-pressed',String(!!entry.interior?.interiorOpen));inside.onclick=()=>{entry.interior.setInterior(!entry.interior.interiorOpen);render();};const s=sim.state.rocket.schedule,active=v&&v.phase!=='home',status=active?`${v.phase.replaceAll('-',' ')} · You + companion + 3 retinue`:v?.returnedHome?'VIP party returned home':'Your VIP party is at home';panel.querySelector('output').textContent=`${status} · Regular ferry ${s.holding?'holding for VIP departure':`in ${Math.ceil(Math.max(0,s.nextArrival-sim.state.seconds)/6)} days`}${s.lastDelay?' · postponed 7 days':''}`;}
// Calling → Inbound → Arrived → Leaving, so the button says where the ship is instead of a second control.
function vipStage(v){if(!v||v.phase==='home')return null;if(['waiting-for-pad','in-transit'].includes(v.phase))return 'Calling';if(v.phase==='descending')return 'Inbound';if(['boarding','ascending','returning'].includes(v.phase))return 'Leaving';return 'Arrived';}
export function createMoonActions(getSimulation,{interior,id,label,embedded=false,refresh}={}){const token=Symbol(),entry={getSimulation,interior,id:id||'standalone-'+String(entries.size),label:label||'Moonbase',embedded,refresh};entries.set(token,entry);return {update:render,dispose(){entries.delete(token);render();}};}
